import sys
import xml.etree.ElementTree as ET
import subprocess
from xml.dom import minidom

def run_recipes(xml_path, html_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        recipes = root.findall('recipe')

        data = []
        for recipe in recipes:
            name = recipe.get('name')
            command_text = recipe.find('command').text.strip()
            if not command_text:
                continue

            try:
                result = subprocess.run(
                    command_text.split(),
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    check=False
                )
                output = result.stdout
                exit_code = result.returncode
                data.append((name, exit_code, output))
            except Exception as e:
                sys.stderr.write(f"Error running command: {e}\n")
                sys.exit(1)

        html = f"""<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Strict//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd">
<html xmlns="http://www.w3.org/1999/xhtml">
<head>
    <title>Recipe Run Report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <h1>Recipe Run Report</h1>
    <table>
        <tr>
            <th>Recipe</th>
            <th>Exit Code</th>
            <th>Output</th>
        </tr>
"""
        for name, exit_code, output in data:
            html += f"""        <tr>
            <td>{name}</td>
            <td>{exit_code}</td>
            <td>{output}</td>
        </tr>
"""
        html += """
    </table>
</body>
</html>
"""

        with open(html_path, 'w') as f:
            f.write(html)

    except (IOError, ET.ParseError) as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python3 run_recipes.py <xml-path> <html-path>\n")
        sys.exit(1)

    run_recipes(sys.argv[1], sys.argv[2])
